def check_rule(text: str):
    raw_sentences = re.split(r'(?<=[.!?])\s+', text.strip())
    sentences = [s.strip() for s in raw_sentences if s.strip()]
    if not sentences:
        return []
    long_sentences = [s for s in sentences if len(s.split()) >= 20]
    if long_sentences:
        return long_sentences
    moderately_long = [s for s in sentences if len(s.split()) >= 15]
    if len(moderately_long) >= max(2, (len(sentences) + 1) // 2):
        return moderately_long
    many_steps = [s for s in sentences if re.match(r'^(First|Second|Third|Fourth|Fifth|Sixth|Seventh|Eighth|Ninth|Tenth)\b', s, re.IGNORECASE)]
    if len(many_steps) >= 4:
        return many_steps
    return []

