import re

def check_rule(text: str):
    lines = text.splitlines()
    heading_re = re.compile(r'^\s{0,3}#{1,6}\s+(.+?)\s*#*\s*$')
    headings = []
    for i, line in enumerate(lines):
        m = heading_re.match(line)
        if m:
            headings.append((i, m.group(1).strip()))
    if not headings:
        return ['No clear heading found to align with page title.']
    first_heading_line, first_heading_text = headings[0]
    if first_heading_line > 0:
        prior_text = '\n'.join(l for l in lines[:first_heading_line]).strip()
        if prior_text:
            return [f'Content appears before the first heading/title: {first_heading_text}']
    return []

