def check_rule(text: str):
    lines = text.splitlines()
    for i, line in enumerate(lines[:-1]):
        if line.rstrip().endswith(':'):
            # Look ahead for a bullet or numbered list item.
            for nxt in lines[i+1:i+5]:
                if re.match(r'^\s*([-*+]|\d+[.)])\s+', nxt):
                    return [line, nxt]
    return []

