def _sentence_count(block: str):
    parts = [p for p in re.split(r'(?<=[.!?])\s+', block.strip()) if p]
    return len(parts)

def check_rule(text: str):
    blocks = [b.strip() for b in re.split(r'\n\s*\n+', text.strip()) if b.strip()]
    for i, block in enumerate(blocks):
        if _sentence_count(block) == 1 and len(block.split()) <= 12:
            if i > 0 and (blocks[i-1].rstrip().endswith(':') or blocks[i-1].endswith('!')):
                return [block]
    return []

