def check_rule(text: str):
    lines = [ln for ln in text.splitlines() if ln.strip()]
    if not lines:
        return []
    short_lines = sum(1 for ln in lines if len(ln.split()) <= 3)
    long_lines = sum(1 for ln in lines if len(ln) > 120)
    if short_lines >= 3 or long_lines >= 2:
        return lines
    return []

