    lines = [ln.strip() for ln in text.splitlines()]
    nonempty = [ln for ln in lines if ln]
    if not nonempty:
        return []

    first_block = nonempty[:12]
    joined = '\n'.join(first_block)

    def strip_md(line: str) -> str:
        return re.sub(r'^#{1,6}\s+', '', line).strip()

    cleaned_block = [strip_md(ln) for ln in first_block]
    cleaned_joined = '\n'.join(cleaned_block)

    body_signals = re.search(r'\b(introduction|findings|recommendations|methodology|discussion|conclusion)\b', cleaned_joined, re.I)
    contents_signals = re.search(r'\bcontents\b', cleaned_joined, re.I)
    if body_signals or contents_signals:
        return []

    has_title = any(
        ln and not re.match(r'^(author|sponsor|prepared by|by|for|subtitle)\b', ln, re.I)
        for ln in cleaned_block[:4]
    )
    has_subtitle = any(':' in ln or re.search(r'\bsubtitle\b', ln, re.I) for ln in cleaned_block)
    has_author = bool(re.search(r'\b(author|prepared by|by)\b\s*[:\-]?', cleaned_joined, re.I))
    has_sponsor = bool(re.search(r'\b(sponsor|commissioned by|for the)\b\s*[:\-]?', cleaned_joined, re.I))

    missing = []
    if not has_title:
        missing.append('title')
    if not has_subtitle:
        missing.append('subtitle')
    if not has_author:
        missing.append('author')
    if not has_sponsor:
        missing.append('sponsor')

    if has_title and missing:
        return missing
    return []

