import re

def check_rule(text: str):
    findings = []
    for line in text.splitlines():
        s = line.strip()
        if not s:
            continue
        m = re.match(r'^(#{1,6}\s+)?(?:(part|chapter)\s+\w+[\.:\-\u2013\u2014]?)\s*(.*)$', s, re.IGNORECASE)
        if not m:
            continue
        kind = m.group(2).lower()
        title = m.group(3).strip()
        title = re.sub(r'^[\s\-:\.|]+', '', title)
        words = re.findall(r"\b[\w'-]+\b", title)
        generic = {
            'introduction', 'overview', 'summary', 'general', 'miscellaneous', 'content', 'section',
            'chapter', 'part', 'details', 'information', 'background', 'context'
        }
        if not title:
            findings.append((kind, 'missing title'))
            continue
        if len(words) > 12:
            findings.append((kind, 'title too long'))
            continue
        if len(words) <= 2 and any(w.lower() in generic for w in words):
            findings.append((kind, 'too generic'))
            continue
        generic_count = sum(1 for w in words if w.lower() in generic)
        if len(words) >= 6 and generic_count >= 2:
            findings.append((kind, 'title too generic/vague'))
    return findings

import re

def check_rule(text: str):
    chapters = []
    for line in text.splitlines():
        s = line.strip()
        if not s:
            continue
        m = re.match(r'^(#{1,6}\s+)?chapter\s+(\d+)\b', s, re.IGNORECASE)
        if m:
            chapters.append(int(m.group(2)))
    if not chapters:
        return []
    expected = list(range(chapters[0], chapters[0] + len(chapters)))
    if chapters != expected:
        return [{'chapters_found': chapters, 'expected': expected}]
    return []

