import re

def check_rule(text: str):
    lines = text.splitlines()
    headings = []
    for line in lines:
        m = re.match(r'^\s{0,3}(#{1,6})\s+(.+?)\s*#*\s*$', line)
        if m:
            headings.append(m.group(2).strip().lower())

    content = text.lower()

    def has_heading(*needles):
        return any(any(n in h for n in needles) for h in headings)

    landing = has_heading('landing page', 'title page', 'cover page') or any(p in content for p in ['landing page', 'title page', 'cover page'])
    preliminary = has_heading('preliminary content', 'contents', 'table of contents', 'foreword', 'preface', 'executive summary') or any(p in content for p in ['preliminary content', 'contents', 'table of contents', 'foreword', 'preface', 'executive summary'])
    body = has_heading('body', 'main body', 'main content') or any(h.startswith('chapter ') for h in headings) or any(p in content for p in ['body', 'main body', 'main content', 'chapter 1'])
    endmatter = has_heading('endmatter', 'end matter', 'appendix', 'appendices', 'references', 'bibliography', 'glossary', 'index') or any(p in content for p in ['endmatter', 'end matter', 'appendix', 'appendices', 'references', 'bibliography', 'glossary', 'index'])

    found = []
    if landing:
        found.append('landing page')
    if preliminary:
        found.append('preliminary content')
    if body:
        found.append('body')
    if endmatter:
        found.append('endmatter')

    return found

