    if re.search(r'ing$', t):
        return False
    if re.search(r'ed$', t):
        return True
    if re.search(r'es$', t):
        return len(t) > 4
    if re.search(r's$', t):
        return len(t) > 3 and not re.search(r'(ss|us|is)$', t)
    return False


def check_rule(text: str):
