    findings = []
    for chunk in chunks:
        words = re.findall(r"[A-Za-z][A-Za-z'’-]*", chunk)
        if not words:
            continue
        if not any(_looks_like_verb(w) for w in words):
            findings.append(chunk)
    return findings

