def check_rule(text: str):
    findings = []
    parts = re.split(r'(?<=[.!?])\s+|\n+', text.strip())
    for part in parts:
        s = part.strip()
        if not s:
            continue
        words = re.findall(r"[A-Za-z][A-Za-z'’-]*", s)
        low = [w.lower() for w in words]
        if len(low) < 4:
            continue
        for i in range(len(low) - 2):
            if low[i] in TRIGGER_VERBS:
                nxt = low[i + 1]
                if nxt in STARTERS:
                    break
                if low[i + 1] not in {'the', 'a', 'an'} and i + 2 < len(low):
                    findings.append(s)
                    break
                if i + 2 < len(low) and low[i + 2] not in STARTERS:
                    findings.append(s)
                    break
    return findings

