        flags=re.I
    )
    copular_pattern = re.compile(
        r'\b(?:is|was|were|are|be|been|being)\s+(?!to\b)(?:sleep|sit|go|leave|wait|work|begin|continue|finish|open|close|write|read|see|hear|move|return)\b',
        flags=re.I
    )
    for seg in segments:
        s = seg.strip()
        if not s:
            continue
        if bare_infinitive_pattern.search(s) or copular_pattern.search(s):
            findings.append(s)
    return findings

