def check_rule(text: str):
    lines = text.splitlines()
    findings = []
    for i, line in enumerate(lines):
        if ':' not in line:
            continue
        if not re.search(r':\s*$', line.strip()):
            continue
        j = i + 1
        items = []
        while j < len(lines):
            m = re.match(r'^\s*(?:[-*+]\s+|\d+[.)]\s+)(.*)$', lines[j])
            if not m:
                break
            items.append(m.group(1).strip())
            j += 1
        if len(items) >= 2 and sum(_looks_like_sentence_or_question(x) for x in items) >= 2:
            findings.append({'lead_in': line, 'items': items})
    return findings

