def _is_list_item(line: str):
    m = re.match(r'^\s*(?:[-*+]\s+|\d+[.)]\s+)(.*)$', line)
    return m.group(1).strip() if m else None


def check_rule(text: str):
    lines = text.splitlines()
    findings = []
    i = 0
    while i < len(lines):
        item = _is_list_item(lines[i])
        if item is None:
            i += 1
            continue
        block = []
        while i < len(lines):
            item = _is_list_item(lines[i])
            if item is None:
                break
            block.append(item)
            i += 1
        if len(block) >= 2:
            last = block[-1].rstrip()
            if not last.endswith('.'):
                fragmenty = all(len(x.split()) <= 8 and not re.search(r'[.!?]$', x) for x in block)
                if fragmenty:
                    findings.append({'items': block})
        else:
            i += 1
    return findings

