def check_rule(text: str):
    findings = []
    lines = text.splitlines()
    in_list = False
    list_buffer = []

    def flush_list(buf):
        if not buf:
            return []
        nonempty = [ln for ln in buf if ln.strip()]
        if not nonempty:
            return []
        items = []
        for ln in nonempty:
            m = re.match(r'^\s*(?:[-*+]|\d+[.)])\s+(.*)$', ln)
            if m:
                items.append(m.group(1).strip())
        if not items:
            return []
        if any(item.endswith(':') for item in items):
            return []
        return [item for item in items if item.endswith('.')]

    for line in lines:
        if re.match(r'^\s*(?:[-*+]|\d+[.)])\s+', line):
            list_buffer.append(line)
        else:
            findings.extend(flush_list(list_buffer))
            list_buffer = []
            if re.match(r'^\s{0,3}#{1,6}\s+.+', line):
                if line.rstrip().endswith('.'):
                    findings.append(line.strip())
    findings.extend(flush_list(list_buffer))
    return findings

