STOPWORDS = {'a','an','the','and','but','or','nor','for','so','yet','at','by','in','of','on','to','up','via','with','from','into','over','as','is'}

def _extract_titles(text: str):
    pattern = r'(?:\*|_){1,2}([^*_\n]+?)(?:\*|_){1,2}'
    return [m.group(1).strip() for m in re.finditer(pattern, text)]

def check_rule(text: str):
    findings = []
    for title in _extract_titles(text):
        words = re.findall(r"[A-Za-z][A-Za-z'\u2019-]*", title)
        if len(words) < 2:
            continue

        major_indices = [i for i, w in enumerate(words) if w.lower() not in STOPWORDS]
        if len(major_indices) < 2:
            continue

        later_major_caps = sum(1 for i in major_indices[1:] if words[i][0].isupper())
        if later_major_caps >= 2:
            findings.append(title)
    return findings

