def check_rule(text: str):
    blocks = [b.strip() for b in re.split(r'\n\s*\n', text.strip()) if b.strip()]
    findings = []
    open_quotes = ('"', '\u201c', '\u2018')
    close_quotes = ('"', '\u201d', '\u2019')

    def starts_with_quote(s):
        return s.lstrip().startswith(open_quotes)

    def ends_with_quote(s):
        return s.rstrip().endswith(close_quotes)

    i = 0
    while i < len(blocks):
        if not starts_with_quote(blocks[i]):
            i += 1
            continue

        run = [blocks[i]]
        j = i + 1
        while j < len(blocks) and starts_with_quote(blocks[j]):
            run.append(blocks[j])
            j += 1

        if len(run) > 1:
            for k, para in enumerate(run):
                if not starts_with_quote(para):
                    findings.append({'paragraph_index': i + k, 'issue': 'missing_open_quote'})
                if k < len(run) - 1 and ends_with_quote(para):
                    findings.append({'paragraph_index': i + k, 'issue': 'premature_close_quote'})

        i = j

    return findings

