def check_rule(text: str):
    findings = []
    parts = re.split(r'([;])', text)

    def is_sentence(segment):
        s = segment.strip()
        if not s:
            return False
        # avoid obvious fragments/headings
        if len(s.split()) < 2:
            return False
        # a crude full-sentence heuristic: ends with sentence punctuation
        return bool(re.search(r'[.!?]["\')\]]*\s*$', s))

    for i in range(1, len(parts), 2):
        left = parts[i - 1]
        right = ''.join(parts[i + 1:]) if i + 1 < len(parts) else ''
        # only inspect the immediate right side up to next strong punctuation/newline
        right = re.split(r'(?<=[.!?])\s|\n', right, maxsplit=1)[0]
        if not (is_sentence(left) and is_sentence(right)):
            findings.append({'semicolon_index': i, 'issue': 'semicolon_not_between_full_sentences'})
    return findings

