def check_rule(text: str):
    lines = text.splitlines()
    headings = []
    for i, line in enumerate(lines):
        s = line.strip()
        if re.match(r'^(#{1,6}\s+)?Glossary\b', s, re.I):
            headings.append(('glossary', i))
        elif re.match(r'^(#{1,6}\s+)?References\b', s, re.I):
            headings.append(('references', i))
    glossary_idx = next((i for t, i in headings if t == 'glossary'), None)
    references_idx = next((i for t, i in headings if t == 'references'), None)
    if glossary_idx is not None and references_idx is not None and glossary_idx < references_idx:
        return [{'issue': 'glossary appears before references'}]
    if re.search(r'\bglossary\b', text, re.I) and not re.search(r'\[[^\]]+\]\([^\)]+\)', text):
        return [{'issue': 'glossary mentioned without a visible hyperlink'}]
    return []

