def check_rule(text: str):
    specialist_pattern = r'\bspecialist terms?\b'
    negated_style_sheet_pattern = r'\b(?:no|not|without)\b[^.?!;:]{0,80}\b(style[ -]?sheet)\b|\b(style[ -]?sheet)\b[^.?!;:]{0,80}\b(?:missing|absent|omitted|not captured|not included|not provided)\b'
    positive_style_sheet_pattern = r'\b(style[ -]?sheet)\b'
    if re.search(specialist_pattern, text, re.I):
        if re.search(negated_style_sheet_pattern, text, re.I):
            return [{'issue': 'specialist terms mentioned without a style sheet'}]
        if not re.search(positive_style_sheet_pattern, text, re.I):
            return [{'issue': 'specialist terms mentioned without a style sheet'}]
    return []

