def check_rule(text: str):
    findings = []
    rank = r'(?:Private|Lance Corporal|Corporal|Sergeant|Warrant Officer|Sub-Lieutenant|Lieutenant|Captain|Major|Lieutenant Colonel|Colonel|Brigadier|Major General|Lieutenant General|General|Midshipman|Sub Lieutenant|Flight Lieutenant|Squadron Leader|Wing Commander|Group Captain|Air Commodore|Air Vice-Marshal|Air Marshal|Marshal|Able Seaman|Leading Seaman|Seaman|Petty Officer|Chief Petty Officer|Warrant Officer|Lieutenant Commander|Commander|Captain|Commodore|Rear Admiral|Vice Admiral|Admiral|Officer Cadet)'
    titles = r'(?:Sir|Dame|the Honourable|Honourable)'
    pat = re.compile(rf'\b{titles}\b.*\b{rank}\b', re.IGNORECASE)
    for i, line in enumerate(text.splitlines(), 1):
        if pat.search(line):
            findings.append({'line': i, 'text': line})
    return findings

