def check_rule(text: str):
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    if len(lines) < 3:
        return []

    rank_re = re.compile(r'^(?:Lieutenant\s+Colonel|Rear\s+Admiral|Vice\s+Admiral|Squadron\s+Leader|Flight\s+Lieutenant|Pilot\s+Officer|Leading\s+Aircraftman|Wing\s+Commander|Lieutenant|Major|Captain|Colonel|Commander|Sergeant|Corporal|Private|Warrant\s+Officer|Officer|Admiral|General|Air\s+Commodore|Air\s+Marshal|Air\s+Vice-Marshal)$', re.IGNORECASE)
    name_re = re.compile(r'^(?:[A-Z][A-Za-z\-\']+|[A-Z]\.)(?:\s+(?:[A-Z][A-Za-z\-\']+|[A-Z]\.))*$', re.IGNORECASE)
    postnom_re = re.compile(r'^[A-Z]{2,}(?:\s*,\s*[A-Z]{2,})*$')
    address_re = re.compile(r'\d|PO Box|Post Office Box|GPO Box|Street|St\b|Road\b|Rd\b|Avenue\b|Ave\b|Unit\b|Level\b', re.IGNORECASE)

    findings = []
    for i in range(len(lines) - 2):
        if not rank_re.match(lines[i]):
            continue
        if not name_re.match(lines[i + 1]):
            continue

        j = i + 2
        if j < len(lines) and postnom_re.match(lines[j]):
            j += 1
        if j < len(lines) and lines[j].upper() == 'RAN':
            j += 1
        if j < len(lines) and lines[j] == '(Retd)':
            j += 1
        if j < len(lines) and address_re.search(lines[j]):
            findings.append({'line': i + 1, 'text': '\n'.join(lines[i:j+1])})
    return findings

import re

def check_rule(text: str):
    findings = []
    lines = [ln.rstrip() for ln in text.splitlines()]
    sal_re = re.compile(r'^(Dear\s+.+|To\s+.+|Sir|Madam|Dear\s+Sir|Dear\s+Madam|Dear\s+Mr\.?\s+.+|Dear\s+Ms\.?\s+.+|Dear\s+Mrs\.?\s+.+|Dear\s+Dr\.?\s+.+)')
    postnom_re = re.compile(r'\b[A-Z]{2,}(?:\s*,\s*[A-Z]{2,})*\b')
    for idx, line in enumerate(lines):
        if sal_re.search(line):
            if line.strip().endswith(','):
                findings.append({'line': idx + 1, 'issue': 'comma-after-salutation', 'text': line})
            if re.search(r'\b[A-Z]{2,}(?:\s*,\s*[A-Z]{2,})+\b', line):
                findings.append({'line': idx + 1, 'issue': 'post-nominals-in-salutation', 'text': line})
            if re.search(r'\b[A-Z]{2,}\b', line) and not line.strip().startswith(('Dear', 'Sir', 'Madam', 'To ')):
                findings.append({'line': idx + 1, 'issue': 'possible-post-nominal-in-salutation', 'text': line})
    return findings

