def check_rule(text: str, lookup_list: list[str]):
    found = []
    allowed = {
        'Commander',
        'Lieutenant Commander',
        'Lieutenant',
        'Lieutenant Colonel',
        'Major',
        'Wing Commander',
        'Squadron Leader',
        'Flight Lieutenant'
    }
    for term in lookup_list:
        if term not in allowed:
            continue
        pattern = re.compile(r'\bDear\s+' + re.escape(term) + r'\s+[A-Z][A-Za-z\-\']+\b', re.IGNORECASE)
        if pattern.search(text):
            found.append(term)
    return found

import re

def check_rule(text: str, lookup_list: list[str]):
    if ',' not in text:
        return []
    found = []
    parts = text.split(',', 1)
    if len(parts) < 2:
        return []
    suffix_text = parts[1].lower()
    for term in lookup_list:
        pattern = r'(?<!\w)' + re.escape(term.lower()) + r'(?!\w)'
        if re.search(pattern, suffix_text):
            found.append(term)
    return found

