def check_rule(text: str, lookup_list: list[str]):
    found = []
    text_lower = text.lower()
    comma_and_pattern = re.compile(r',\s*and\b')
    standalone_pattern = re.compile(r'\b(?:or|but)\b')

    for term in lookup_list:
        term_lower = term.lower()
        if term_lower == 'and':
            if comma_and_pattern.search(text_lower):
                found.append(term)
        elif standalone_pattern.search(text_lower) and re.search(r'\b' + re.escape(term_lower) + r'\b', text_lower):
            found.append(term)
    return found

