def check_rule(text: str, lookup_list: list[str]):
    found = []
    text_lower = text.lower().strip()

    start_pattern = re.compile(r'^with\s+(?!care\b)[^,.!?;]+,')
    end_pattern = re.compile(r',\s*with\s+[^.?!]+[.?!]?$')

    for term in lookup_list:
        if term.lower() == 'with':
            if start_pattern.search(text_lower) or end_pattern.search(text_lower):
                found.append(term)
        else:
            pattern = r'\b' + re.escape(term.lower()) + r'\b'
            if re.search(pattern, text_lower):
                found.append(term)
    return found

