DETERMINERS = {
    'a', 'an', 'the', 'this', 'that', 'these', 'those', 'my', 'your', 'his', 'her',
    'its', 'our', 'their', 'some', 'any', 'each', 'every', 'no', 'either', 'neither',
    'many', 'much', 'few', 'several', 'enough', 'what', 'which', 'such'
}


def check_rule(text: str):
    findings = []
    # Split into lines and sentence-like chunks for a lightweight structural check.
    chunks = re.split(r'(?<=[.!?])\s+|\n+', text.strip())
    for chunk in chunks:
        s = chunk.strip()
        if not s:
            continue
        tokens = re.findall(r"[A-Za-z]+(?:'[A-Za-z]+)?|\d+|\S", s)
        for i, tok in enumerate(tokens):
            low = tok.lower()
            if low in DETERMINERS:
                # Look ahead a short distance for a likely noun (word-like token not in stop set).
                window = tokens[i + 1:i + 5]
                if not window:
                    findings.append(s)
                    break
                # If determiner is followed by punctuation or another determiner, likely no noun.
                next_word = next((w for w in window if re.match(r'^[A-Za-z0-9]', w)), None)
                if next_word is None:
                    findings.append(s)
                    break
                if next_word.lower() in DETERMINERS:
                    findings.append(s)
                    break
    return findings

