INTRODUCERS = {
    'a', 'an', 'the', 'this', 'that', 'these', 'those', 'my', 'your', 'his', 'her',
    'its', 'our', 'their', 'some', 'any', 'each', 'every', 'no', 'either', 'neither',
    'many', 'much', 'few', 'several', 'enough', 'what', 'which', 'such'
}


def check_rule(text: str):
    findings = []
    chunks = re.split(r'(?<=[.!?])\s+|\n+', text.strip())
    for chunk in chunks:
        s = chunk.strip()
        if not s:
            continue
        # Focus on line/sentence starts where determiners are likely to introduce noun phrases.
        tokens = re.findall(r"[A-Za-z]+(?:'[A-Za-z]+)?|\d+|\S", s)
        if not tokens:
            continue
        first = tokens[0].lower()
        if first in INTRODUCERS:
            # Require a plausible noun-like token soon after.
            following = [t for t in tokens[1:5] if re.match(r'^[A-Za-z0-9]', t)]
            if not following:
                findings.append(s)
                continue
            if following[0].lower() in INTRODUCERS:
                findings.append(s)
                continue
            # If the chunk is just a determiner phrase without an obvious noun, flag.
            if len(following) == 1 and len(s.split()) <= 2:
                findings.append(s)
    return findings

