DETERMINER_STARTS = {
    'a', 'an', 'the', 'those', 'these', 'this', 'that', 'my', 'your', 'his', 'her',
    'its', 'our', 'their', 'some', 'any', 'many', 'much', 'few', 'several', 'each',
