}


def check_rule(text: str):
    findings = []
    chunks = re.split(r'(?<=[.!?])\s+|\n+', text.strip())
    for chunk in chunks:
        s = chunk.strip()
        if not s:
            continue
        tokens = re.findall(r"[A-Za-z]+(?:'[A-Za-z]+)?|\d+(?:,\d{3})*(?:\.\d+)?|\S", s)
        if len(tokens) < 2:
            continue
        first = tokens[0].lower()
        if first in DETERMINER_STARTS or re.fullmatch(r'\d+(?:,\d{3})*(?:\.\d+)?', tokens[0]):
            # Numeric determiners can be multiword, so allow number + optional unit/word.
            if re.fullmatch(r'\d+(?:,\d{3})*(?:\.\d+)?', tokens[0]):
                findings.append(s)
            else:
                if any(re.match(r'^[A-Za-z]', t) for t in tokens[1:4]):
                    findings.append(s)
    return findings

