        if not tokens:
            continue
        first = tokens[0].lower()
        if first in PRONOUN_DETERMINERS:
            following = [t for t in tokens[1:5] if re.match(r'^[A-Za-z0-9]', t)]
            if not following:
                findings.append(s)
