def check_rule(text: str):
    findings = []
    chunks = re.split(r'(?<=[.!?])\s+|\n+', text.strip())
    for chunk in chunks:
        s = chunk.strip()
        if not s:
            continue
        tokens = re.findall(r"\d+(?:,\d{3})*(?:\.\d+)?|[A-Za-z]+(?:'[A-Za-z]+)?|\S", s)
        if not tokens:
            continue
        if re.fullmatch(r'\d+(?:,\d{3})*(?:\.\d+)?', tokens[0]):
            findings.append(s)
            continue
        # Also catch number phrases like '23 million people...'
        if len(tokens) >= 2 and re.fullmatch(r'\d+(?:,\d{3})*(?:\.\d+)?', tokens[0]) and re.match(r'^[A-Za-z]', tokens[1]):
            findings.append(s)
    return findings

