def check_rule(text: str):
    sentences = re.split(r'(?<=[.!?])\s+|\n+', text.strip())
    findings = []
    nounish = re.compile(r'^(?:[A-Z][a-z]+(?:-[A-Z][a-z]+)?|[A-Z]{2,}|[a-z]+(?:-[a-z]+)?)$')
    for s in sentences:
        tokens = re.findall(r"\b[\w-]+\b", s)
        run = 0
        for tok in tokens:
            if nounish.match(tok) and tok.lower() not in {'the', 'and', 'or', 'but', 'for', 'with', 'from', 'into', 'onto', 'over', 'under', 'in', 'on', 'at', 'by', 'to', 'of', 'a', 'an'}:
                run += 1
                if run >= 3:
                    findings.append(s)
                    break
            else:
                run = 0
    return findings

