def check_rule(text: str):
    findings = []
    if not text.strip():
        return findings
    # Flag bracketed/parenthetical insertions and comma-delimited clauses as possible non-essential info.
    patterns = [
        r'\([^\n]{3,120}\)',
        r'\[[^\n]{3,120}\]',
        r',\s*[^,\n]{3,120}\s*,',
    ]
    for pat in patterns:
        for m in re.finditer(pat, text):
            findings.append(m.group(0))
    return findings

