def check_rule(text: str):
    fired = []

    # Heuristic lists for long works/compilations vs songs.
    long_works = [r'\bsymphony\b', r'\bconcerto\b', r'\bsonata\b', r'\bsuite\b', r'\bmass\b', r'\bcompilation\b', r'\balbum\b']
    songs = [r'\bsong\b', r'\bhymn\b', r'\ballad\b']

    has_italic_markers = bool(re.search(r'\*[^*]+\*|_[^_]+_', text))

    if any(re.search(p, text, flags=re.IGNORECASE) for p in long_works):
        # If long works are mentioned without italics markers at all, flag.
        if not has_italic_markers:
            fired.append('Long work or compilation appears without italics.')

    if any(re.search(p, text, flags=re.IGNORECASE) for p in songs):
        # If song-like items are marked with italics, flag.
        if has_italic_markers:
            fired.append('Song appears to be italicised; songs should be roman type.')

    return fired

