def check_rule(text: str):
    findings = []
    title_patterns = [r'"([^"]{2,120})"', r'“([^”]{2,120})”', r'\*([^*]{2,120})\*', r'_(.{2,120}?)_']
    for pat in title_patterns:
        for m in re.finditer(pat, text):
            title = m.group(1).strip()
            if len(title.split()) > 8:
                continue
            before = text[max(0, m.start() - 120):m.start()]
            after = text[m.end():min(len(text), m.end() + 120)]
            context = before + after
            if not re.search(r'\bhymn(?:s)?\b', context, flags=re.I):
                continue
            words = re.findall(r"[A-Za-z][A-Za-z'’-]*", title)
            if not words:
                continue
            upper_ratio = sum(w.isupper() for w in words) / len(words)
            title_case_words = sum(w[0].isupper() for w in words if w) / len(words)
            if upper_ratio > 0.6 or title_case_words > 0.7:
                findings.append({'match': title})
                continue
            if not (m.start() > 0 and m.end() < len(text) and text[m.start()-1] == "'" and text[m.end()] == "'"):
                findings.append({'match': title})
    return findings

