def check_rule(text: str):
    findings = []

    # 1. Quoted long-work titles are likely not italicised.
    for m in re.finditer(r'"([^"]{2,160})"|“([^”]{2,160})”', text):
        title = (m.group(1) or m.group(2)).strip()
        if len(title.split()) >= 2:
            findings.append({'match': title})

    # 2. Detect likely unitalicised long-work titles after common cues.
    patterns = [
        r'\b(featured|included|studied|performed|heard|presented)\s+([A-Z][A-Za-z0-9.,’\'\- ]{2,120}?)(?=\s+by\b|\s+in\b|\s+as\b|\s+for\b|\s+on\b|\.|,|;|:|$)',
        r'\b(symphony|opera|cantata|oratorio|sonata|suite|concerto|ballet)\s+([A-Z][A-Za-z0-9.,’\'\- ]{1,120}?)(?=\s+by\b|\s+in\b|\s+as\b|\s+for\b|\s+on\b|\.|,|;|:|$)'
    ]

    for pattern in patterns:
        for m in re.finditer(pattern, text, flags=re.I):
            title = (m.group(2) if m.lastindex and m.lastindex >= 2 else m.group(1)).strip()
            title = re.sub(r'^(the)\s+', '', title, flags=re.I).strip()
            if not title:
                continue
            if title.startswith('*') and title.endswith('*'):
                continue
            if title.startswith('_') and title.endswith('_'):
                continue
            if re.fullmatch(r'(?i)(opera|symphony|cantata|oratorio|sonata|suite|concerto|ballet)', title):
                continue
            findings.append({'match': title})

    # Deduplicate findings.
    unique = []
    seen = set()
    for item in findings:
        key = item['match']
        if key not in seen:
            seen.add(key)
            unique.append(item)
    return unique

