def check_rule(text: str):
    findings = []
    lines = text.splitlines()

    quote_pattern = re.compile(r'(^\s*>\s+|"[^"]+"|“[^”]+”|‘[^’]+’)', re.M)
    citation_with_pages = re.compile(r'\(([^\)]*?\d{4}[^\)]*?(?:[:;,]\s*|\bpp?\.?\s*)\d+[^\)]*)\)')
    citation_no_pages = re.compile(r'\(([^\)]*?\d{4}[^\)]*)\)')

    if quote_pattern.search(text):
        quoted_segments = [m.group(0) for m in quote_pattern.finditer(text)]
        for seg in quoted_segments:
            start = max(0, text.find(seg) - 120)
            end = min(len(text), text.find(seg) + len(seg) + 180)
            window = text[start:end]
            if citation_with_pages.search(window):
                findings.append(window.strip())
            elif citation_no_pages.search(window):
                findings.append(window.strip())

    return findings

