def check_rule(text: str):
    lines = text.splitlines()
    headings = []
    for i, line in enumerate(lines):
        if re.match(r'^\s{0,3}#{1,6}\s+References\s*$', line, re.I) or re.match(r'^\s*References\s*$', line, re.I):
            headings.append((i, 'references'))
        elif re.match(r'^\s{0,3}#{1,6}\s+Appendix(?:es)?\b', line, re.I) or re.match(r'^\s*Appendix(?:es)?\b', line, re.I):
            headings.append((i, 'appendix'))
        elif re.match(r'^\s{0,3}#{1,6}\s+Index\s*$', line, re.I) or re.match(r'^\s*Index\s*$', line, re.I):
            headings.append((i, 'index'))

    if not any(kind == 'references' for _, kind in headings):
        return []

    refs = [i for i, kind in headings if kind == 'references']
    app = [i for i, kind in headings if kind == 'appendix']
    idx = [i for i, kind in headings if kind == 'index']
    ref_i = refs[0]

    # Flag if references is not the last major section in a webpage-like document.
    if not app and not idx:
        after = lines[ref_i + 1:]
        for line in after:
            if re.match(r'^\s{0,3}#{1,6}\s+\S+', line):
                return ["References is not the final section"]
        return []

    # Print-like heuristic: references should come after appendices and before index.
    if app and ref_i < max(app):
        return ["References appears before appendices"]
    if idx and ref_i > min(idx):
        return ["References appears after index"]
    if app and idx and not (max(app) < ref_i < min(idx)):
        return ["References is not between appendices and index"]

    return []

