def check_rule(text: str):
    # Detect in-text author-date citations like (Smith 2020) or Smith (2020)
    in_text = re.findall(r'\(([^()]{2,80}?\b\d{4}[a-z]?[^()]*)\)', text)
    cited_keys = set()
    for cit in in_text:
        m = re.search(r'([A-Z][A-Za-z\-\'’]+)', cit)
        y = re.search(r'\b(\d{4}[a-z]?)\b', cit)
        if m and y:
            cited_keys.add((m.group(1).lower(), y.group(1)))
    # Collect reference-list-like lines
    ref_lines = []
    for line in text.splitlines():
        if re.match(r'^\s*(?:[-*+]\s+)?[A-Z][A-Za-z\-\'’]+', line):
            ref_lines.append(line.strip())
    ref_keys = set()
    for line in ref_lines:
        m = re.match(r'^(?:[-*+]\s+)?([A-Z][A-Za-z\-\'’]+)', line)
        y = re.search(r'\b(\d{4}[a-z]?)\b', line)
        if m and y:
            ref_keys.add((m.group(1).lower(), y.group(1)))
    missing = []
    for key in cited_keys:
        if key not in ref_keys:
            missing.append({'missing_reference_for': f'{key[0]} {key[1]}'})
    return missing

