def check_rule(text: str):
    findings = []
    for i, line in enumerate(text.splitlines(), 1):
        s = line.strip()
        if not s:
            continue
        if not re.search(r'\b(19|20)\d{2}\b', s):
            continue
        parts = [p.strip() for p in re.split(r'\s*;\s*', s) if p.strip()]
        if len(parts) < 3:
            continue
        date_idx = next((idx for idx, p in enumerate(parts) if re.search(r'\b(19|20)\d{2}\b', p)), None)
        if date_idx is None:
            continue
        author_like = bool(re.match(r'^[A-Z][A-Za-z\-\'’\.]+(?:\s+[A-Z][A-Za-z\-\'’\.]+){0,5}$', parts[0]))
        publisher_like = any(re.search(r'\b(publisher|press|department|government|commonwealth|australia|canberra)\b', p, re.I) or ':' in p for p in parts)
        if date_idx == 0:
            findings.append({'line': i, 'issue': 'possible_wrong_note_order'})
            continue
        if not author_like:
            findings.append({'line': i, 'issue': 'possible_wrong_note_order'})
            continue
        if len(parts) >= 3 and date_idx > 1:
            second = parts[1]
            third = parts[2]
            second_looks_publisher = bool(re.search(r'\b(publisher|press|department|government|commonwealth|australia|canberra)\b', second, re.I) or ':' in second)
            third_looks_title = not bool(re.search(r'\b(publisher|press|department|government|commonwealth|australia|canberra)\b', third, re.I) or ':' in third)
            if second_looks_publisher and third_looks_title:
                findings.append({'line': i, 'issue': 'possible_wrong_note_order'})
                continue
        if not publisher_like:
            continue
        if 'accessed' in s.lower() and date_idx == len(parts) - 1:
            findings.append({'line': i, 'issue': 'accessed_date_order_unclear'})
    return findings

