def check_rule(text: str):
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    note_lines = [ln for ln in lines if re.match(r'^(\d+\.|\[\d+\]|\d+\)|\^\d+|[A-Za-z][A-Za-z0-9 .,&\-()]+\d{4})', ln)]
    # Detect repeated identical note entries, which suggests the same full citation is being reused.
    norm = []
    for ln in note_lines:
        s = re.sub(r'\s+', ' ', ln.lower())
        s = re.sub(r'^[\[\(]?\d+[\]\)\.]?\s*', '', s)
        norm.append(s)
    counts = {}
    for n in norm:
        counts[n] = counts.get(n, 0) + 1
    repeated = [n for n, c in counts.items() if c > 1]
    # Also flag if a document has two or more notes mentioning the same apparent source heading.
    source_keys = []
    for ln in note_lines:
        m = re.search(r'([A-Z][A-Za-z&\- ]{2,}?)\s+(\d{4})', ln)
        if m:
            source_keys.append((m.group(1).strip().lower(), m.group(2)))
    source_counts = {}
    for k in source_keys:
        source_counts[k] = source_counts.get(k, 0) + 1
    repeated_sources = [k for k, c in source_counts.items() if c > 1]
    return repeated or repeated_sources

