        return []
    findings = []
    # Split into heading sections.
    sections = []
    for idx, (start_i, heading) in enumerate(headings):
        end_i = headings[idx + 1][0] if idx + 1 < len(headings) else len(lines)
        sections.append((heading, lines[start_i + 1:end_i]))
    for heading, sec_lines in sections:
        note_lines = []
        for ln in sec_lines:
            s = ln.strip()
            if re.match(r'^(\d+\.|\[\d+\]|\d+\)|\^\d+)\s*', s):
