def check_rule(text: str):
    findings = []
    abbr_pat = r'\s*\((?:[A-Z]{2,5}|[A-Z][a-z]{1,9}(?:\.[A-Z]{2})?)\)'

    # Flag italicised foreign legislation titles only when no country abbreviation follows.
    title_pat = re.compile(r'([*_][^*_\n]{2,120}(?:Act|Law|Code|Decree|Ordinance)[^*_\n]{0,120}[*_])')
    italic_spans = []
    for m in title_pat.finditer(text):
        italic_spans.append(m.span())
        end = m.end(1)
        window = text[end:end+30]
        if not re.match(abbr_pat, window):
            findings.append(m.group(1))

    # Also flag bare legislation-like titles with no abbreviation nearby,
    # but ignore titles already captured inside italics and known Australian legislation.
    bare_pat = re.compile(r'\b(?:the\s+)?[A-Z][A-Za-z&\-]*(?:\s+[A-Z][A-Za-z&\-]*)*\s+(?:Act|Law|Code|Decree|Ordinance)\b')
    domestic_terms = {'Australian Consumer Law'}
    for m in bare_pat.finditer(text):
        span = m.span()
        if any(span[0] >= s and span[1] <= e for s, e in italic_spans):
            continue
        title = m.group(0).strip()
        title_core = re.sub(r'^the\s+', '', title)
        if title_core in domestic_terms:
            continue
        end = m.end(0)
        window = text[end:end+30]
        if not re.match(abbr_pat, window):
            findings.append(title)
    return findings

