def check_rule(text: str):
    lines = text.splitlines()
    heading_re = re.compile(r'^(#{1,6})\s+(.*\S)\s*$')
    list_re = re.compile(r'^(?:[-*+]\s+|\d+[.)]\s+)(.*\S)\s*$')

    headings = []
    for i, line in enumerate(lines):
        m = heading_re.match(line.strip())
        if m:
            level = len(m.group(1))
            title = m.group(2).strip().lower()
            headings.append((i, level, title))

    def collect_under(target_title):
        for idx, level, title in headings:
            if title == target_title:
                items = []
                for j in range(idx + 1, len(lines)):
                    hm = heading_re.match(lines[j].strip())
                    if hm and len(hm.group(1)) <= level:
                        break
                    lm = list_re.match(lines[j].strip())
                    if lm:
                        items.append(lm.group(1).strip())
                return items
        return None

    findings = []
    for target in ('legislation', 'legal cases'):
        items = collect_under(target)
        if items is None or len(items) < 2:
            continue
        normalized = [re.sub(r'^["\'“”‘’\(\[]+|["\'“”‘’\)\],.;:]+$', '', item).strip().lower() for item in items]
        if normalized != sorted(normalized):
            findings.append({'heading': target, 'items': items})

    return findings

