    nav_section = False
    nav_items = []
    sections = []
    current = []
    heading_re = re.compile(r'^(#{1,6})\s+(.+)$')
    list_re = re.compile(r'^(?:[-*+]\s+|\d+[.)]\s+)(.+)$')

    def flush():
        nonlocal current
        if current:
            sections.append(current)
            current = []

    for ln in lines:
        stripped = ln.strip()
        if not stripped:
            if nav_section:
                flush()
            continue
        m = heading_re.match(stripped)
        if m:
            title = m.group(2).strip().lower()
            if 'nav' in title or 'menu' in title or 'table of contents' in title:
                nav_section = True
            else:
                if nav_section:
                    flush()
                nav_section = False
            continue
        if nav_section:
            lm = list_re.match(stripped)
            if lm:
                current.append(lm.group(1).strip())
    flush()

    if len(sections) >= 2:
        norm = [tuple(sec) for sec in sections if sec]
        if len(set(norm)) > 1:
            return ['Inconsistent navigation elements or order detected']
    return []

