def _tense(item: str) -> str:
    s = item.strip().lower()
    words = _WORD_RE.findall(s)
    if not words:
        return 'unknown'

    if re.match(r'^to\b', s):
        return 'infinitive'

    if 'will' in words or 'shall' in words:
        return 'future'

    if re.search(r'\b(am|is|are|was|were)\b\s+\w+ing\b', s):
        return 'progressive'

    if re.search(r'\b(was|were|had|did)\b', s) or re.search(r'\b\w+ed\b', s):
        return 'past'

    if re.search(r'\b(am|is|are|do|does|have|has)\b', s):
        return 'present'

    first = words[0]
    if first.endswith('ing'):
        return 'gerund'
    if first.endswith('ed'):
        return 'past'

    return 'base_or_adjectival'


