    first = blocks[0].lower()
    second = blocks[1].lower()

    summary_cues = re.search(r'\b(summary|overview|brief summary|in short|at a glance|key points?|the main point|we recommend|this note explains|this document explains)\b', first)
    detail_cues_later = any(re.search(r'\b(further|detail|details|background|more detail|background information|in addition|later|subsequently|the following)\b', b.lower()) for b in blocks[1:])

    if summary_cues:
        return []

    # Fire if the document starts with non-summary background and detail appears after.
    if re.search(r'\b(background|introduction|context|history|about|overview of the issue)\b', first) and detail_cues_later:
        return ['Document should start with a brief summary before the detail.']

    # Fire if a clearer summary-like block appears later than the opening.
