    later_refs_back = any(re.search(r'\b(as above|previously|earlier|mentioned above|as noted|back to|return to)\b', b.lower()) for b in blocks[1:])
    jumps = any(re.search(r'\b(finally|lastly|in conclusion|afterwards|next)\b', blocks[i].lower()) and re.search(r'\b(first|initially|before that|earlier)\b', blocks[i+1].lower()) for i in range(len(blocks)-1))

    if later_refs_back or jumps:
