from collections import defaultdict

def _marker_type(line: str):
    m = re.match(r'^(\s*)([-*+]|\d+[.)]|[a-zA-Z][.)]|\u2013|\u2014|\u2022|\u25e6)\s+', line)
    if not m:
        return None
    indent = len(m.group(1))
    marker = m.group(2)
    if re.match(r'^\d+[.)]$', marker):
        kind = f'number:{marker[-1]}'
    elif re.match(r'^[a-zA-Z][.)]$', marker):
        kind = f'letter:{marker[-1]}'
    elif marker in {'-', '*', '+', '\u2022', '\u25e6', '\u2013', '\u2014'}:
        kind = f'bullet:{marker}'
    else:
        kind = f'other:{marker}'
    return indent, kind, marker

def check_rule(text: str):
    level_kinds = defaultdict(set)
    findings = []
    for line_no, line in enumerate(text.splitlines(), start=1):
        info = _marker_type(line)
        if not info:
            continue
        indent, kind, marker = info
        level_kinds[indent].add(kind)
        if len(level_kinds[indent]) > 1:
            findings.append({'line': line_no, 'text': line.strip(), 'reason': 'mixed markers at same indentation level'})
    return findings

