def check_rule(text: str):
    paragraphs = [p.strip() for p in re.split(r'\n\s*\n+', text.strip()) if p.strip()]

    def first_sentence(p):
        parts = re.split(r'(?<=[.!?])\s+', p, maxsplit=1)
        return parts[0].strip() if parts else p.strip()

    def wc(s):
        return len(re.findall(r"\b\w+\b", s))

    findings = []
    for p in paragraphs:
        sent = first_sentence(p)
        if wc(sent) == 0:
            continue

        intro_cue = re.match(
            r'^(this|these|the|to|for|when|if|because|you|we|our|in this|this page|this guide|it|they)\b',
            sent,
            re.I,
        )

        leadin = re.match(r'^(after|before|while|during|following|given|under|in|on|at|by|with|without|despite)\b', sent, re.I)
        comma_count = sent.count(',')

        if wc(sent) > 25 or (leadin and comma_count >= 2) or (not intro_cue and wc(sent) > 12):
            findings.append(p)

    return findings

