def check_rule(text: str):
    findings = []

    # Sentence-start checks on plain text paragraphs.
    sentences = re.split(r'(?<=[.!?])\s+', text.strip()) if text.strip() else []
    for s in sentences:
        s2 = s.strip()
        if not s2:
            continue
        if re.match(r'^["\'\(\[\{]*[a-z]', s2):
            findings.append(s2)

    # Heading checks in markdown-like text.
    for ln in text.splitlines():
        line = ln.strip()
        if not line:
            continue
        if re.match(r'^#{1,6}\s+[a-z]', line):
            findings.append(line)
        # Also catch standalone ATX-style headings without markdown hash, often title lines.
        if re.match(r'^[a-z][^.!?]*$', line) and len(line.split()) <= 12 and line[0].islower():
            # Avoid flagging regular body lines by requiring short, title-like lines.
            findings.append(line)

    return findings

