def check_rule(text: str):
    # Heuristic only: flag sentences that appear to use non-standard/wordy inversion.
    findings = []
    sentences = re.split(r'(?<=[.!?])\s+', text.strip()) if text.strip() else []
    fronted_patterns = [
        r'^\s*(?i:(in|on|at|for|with|from|by|after|before|during|under|over|through|because of|due to|in order to)\b)',
        r'^\s*(?i:(there|here)\s+is\b)',
        r'^\s*(?i:(it|this|that)\s+is\b)',
    ]
    for s in sentences:
        s2 = s.strip()
        if not s2:
            continue
        if any(re.search(p, s2) for p in fronted_patterns):
            # Only flag when the sentence also looks clause-heavy/less direct.
            if len(s2.split()) >= 8:
                findings.append(s2)
    return findings

