def check_rule(text: str):
    findings = []
    sentences = re.split(r'(?<=[.!?])\s+', text.strip()) if text.strip() else []
    be = r'(?i:\b(?:am|is|are|was|were|be|been|being)\b)'
    passive = re.compile(rf'{be}\s+(?:\w+ed|\w+en|\w+wn|\w+ne|given|made|known|seen|done|taken|sent|built|read|kept|left|put|set|held|found|brought|told)\b(?:\s+by\b)?', re.I)
    for s in sentences:
        s2 = s.strip()
        if not s2:
            continue
        if passive.search(s2):
            findings.append(s2)
    return findings

