from urllib.parse import urlparse

def check_rule(text: str):
    urls = []
    for m in re.finditer(r'(?i)\bhttps?://[^\s)\]">]+', text):
        urls.append(m.group(0).rstrip('.,;'))
    for m in re.finditer(r'(?mi)^(?:url|permalink|canonical)\s*[:=]\s*(\S+)', text):
        urls.append(m.group(1).strip())
    findings = []
    generic = {'home', 'page', 'post', 'article', 'index', 'content', 'section', 'node'}
    for u in urls:
        parsed = urlparse(u)
        path = parsed.path.strip('/')
        if not path:
            continue
        first = path.split('/')[0]
        first_clean = re.sub(r'[^a-z0-9-]+', '', first.lower())
        if len(first_clean) > 25 or first_clean in generic or not first_clean:
            findings.append(f'URL may not place main keywords near the start: {u}')
    return findings

import re
from urllib.parse import urlparse

def check_rule(text: str):
    urls = []
    for m in re.finditer(r'(?i)\bhttps?://[^\s)\]">]+', text):
        urls.append(m.group(0).rstrip('.,;'))
    for m in re.finditer(r'(?mi)^(?:url|permalink|canonical)\s*[:=]\s*(\S+)', text):
        urls.append(m.group(1).strip())
    findings = []
    for u in urls:
        if len(u) > 100:
            findings.append(f'URL is longer than 100 characters: {u}')
            continue
        parsed = urlparse(u)
        path = parsed.path.strip('/')
        if path:
            segments = [s for s in path.split('/') if s]
            if not any(re.search(r'[a-zA-Z]', s) for s in segments):
                findings.append(f'URL may not be meaningful to users: {u}')
        elif parsed.query:
            findings.append(f'URL may not be meaningful to users: {u}')
    return findings

import re

def check_rule(text: str):
    titles = []
    fm = re.search(r'(?s)^---\s*.*?\btitle\s*:\s*(.+?)\n.*?---', text, re.I)
    if fm:
        titles.append(fm.group(1).strip().strip('"\''))
    for m in re.finditer(r'(?im)^(?:title|page title)\s*[:=]\s*(.+)$', text):
        titles.append(m.group(1).strip().strip('"\''))
    h1 = re.search(r'(?m)^#\s+(.+)$', text)
    if h1:
        titles.append(h1.group(1).strip())
    findings = []
    if not titles:
        return []
    generic = {'home', 'welcome', 'overview', 'page', 'untitled', 'document'}
    keyword_pattern = re.compile(r'\b[a-zA-Z]{4,}\b')
    for t in titles:
        if len(t) > 70:
            findings.append(f'title exceeds 70 characters: {t}')
        if t.strip().lower() in generic:
            findings.append(f'title appears too generic: {t}')
        if keyword_pattern.search(t):
            findings.append(f'title includes keywords: {t}')
    return findings

