from collections import Counter

def check_rule(text: str):
    titles = []
    fm = re.search(r'(?s)^---\s*.*?\btitle\s*:\s*(.+?)\n.*?---', text, re.I)
    if fm:
        titles.append(fm.group(1).strip().strip('"\''))
    for m in re.finditer(r'(?im)^(?:title|page title)\s*[:=]\s*(.+)$', text):
        titles.append(m.group(1).strip().strip('"\''))
    h1s = re.findall(r'(?m)^#\s+(.+)$', text)
    titles.extend([t.strip() for t in h1s])
    if not titles:
        return []
    counts = Counter(t.lower() for t in titles if t)
    findings = []
    for title, n in counts.items():
        if n > 1 and title not in {'home', 'overview', 'page', 'document', 'untitled'}:
            findings.append(f'duplicate title found: {title}')
    return findings

