def check_rule(text: str):
    findings = []
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    meta_lines = []
    for ln in lines:
        if re.match(r'^(meta description|description)\s*[:\-]', ln, re.I):
            meta_lines.append(ln)
        elif re.match(r'^<meta\s+name=["\']description["\']\s+content=["\'].*["\']\s*/?>$', ln, re.I):
            meta_lines.append(ln)
    for ln in meta_lines:
        m = re.search(r'[:\-]\s*(.*)$', ln)
        content = m.group(1) if m else ln
        if len(content) > 160:
            findings.append({'line': ln, 'reason': 'meta description exceeds 160 characters'})
        # crude structural heuristic: very short or repetition-heavy descriptions are unlikely to be user-focused
        words = re.findall(r"\b\w+[\w'-]*\b", content.lower())
        if len(words) >= 8:
            unique_ratio = len(set(words)) / len(words)
            if unique_ratio < 0.5:
                findings.append({'line': ln, 'reason': 'meta description appears repetitive and may not be user-focused'})
    return findings

