def check_rule(text: str, lookup_list: list[str]):
    found = []
    text_lower = text.lower()
    keyword_patterns = [
        r'\bkeywords?\b',
        r'\bkeyword\s+phrase\b',
        r'\bdescriptive\s+keyword\b',
        r'\btopic\s+keyword\b'
    ]
    for pattern in keyword_patterns:
        if re.search(pattern, text_lower):
            found.append(re.search(pattern, text_lower).group(0))
    for term in lookup_list:
        pattern = r'\b' + re.escape(term.lower()) + r'\b'
        if re.search(pattern, text_lower):
            found.append(term)
    return found

