def check_rule(text: str):
    findings = []
    paragraphs = re.split(r'\n\s*\n', text.strip()) if text.strip() else []
    marking_pattern = r'protective marking(?:s)?|marked as|marked appropriately'
    for p in paragraphs:
        if re.search(r'\bsecurity-classified information\b|\bclassified information\b', p, re.I):
            if not re.search(marking_pattern, p, re.I):
                findings.append({'paragraph': p[:200], 'reason': 'security-classified information without protective markings'})
        if re.search(r'\bemail(?:s)?\b', p, re.I) and re.search(r'\bclassified\b', p, re.I):
            if not re.search(marking_pattern, p, re.I):
                findings.append({'paragraph': p[:200], 'reason': 'classified email without protective markings'})
    return findings

